def name_operands(region,address,operation):
 if region=='D3D' and address in FUNCTIONS:
  for old,new in (('LD HL, #F581','LD HL, @PreviewShipText.Dominion'),('LD HL, #FBD8','LD HL, @PreviewSkimText.Fervest'),('(#E146)','(@D3DPreviewState.RowOperand)'),('(#E148)','(@D3DPreviewState.BaseOperand)'),('CALL #A390','CALL @Station.SkipLfRecords.Entry'),('CALL #A82D','CALL @Station.CountTextRows.Entry'),('CALL #A843','CALL @Station.PrintFromRow.Entry')):operation=operation.replace(old,new)
  target=0xE12D if address==0xE124 else 0xE15E
  operation=operation.replace('JR NZ, #'+format(target,'04X'),'JR NZ, @D3D.'+FUNCTIONS[address][0]+'.SelectedText')
 if region=='Station' and address in (0x6952,0x6963):operation=operation.replace('CALL #E124','CALL @D3D.CountPreviewTextRows.Entry').replace('CALL #E154','CALL @D3D.PrintPreviewTextRows.Entry')
 return operation
